rows=[]
for r in rs:
 for f in r['fractions']:
  for n,m in f['selections'].items():rows.append(dict(support=r['id'],q=f['q'],map=n,**{k:v for k,v in m.items() if not isinstance(v,(dict,list))},centroid_x_local=m['centroid_xy_local'][0],centroid_y_local=m['centroid_xy_local'][1]))
